definition:
CREATE OR REPLACE FUNCTION public.fn_union_pnl_evidence_report(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_open jsonb; v_close jsonb; v_issues jsonb:='[]'; v_clubs jsonb; v_eco jsonb; v_terms jsonb;
 v_fence timestamptz; v_bad bigint; v_hands bigint; v_resolved bigint:=0; v_rows bigint; v_cash_reconciled boolean; v_terms_value jsonb; v_cash_rake numeric; v_accepted_rake numeric;
 v_memo_key text; v_memo jsonb; v_report jsonb; v_flows jsonb; v_open_resolved uuid[];
 v_inv boolean; v_cash boolean; v_credit boolean;
 v_cert jsonb; v_generation text;
BEGIN
 IF p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end)
  OR p_start<>public.fn_union_week_start(p_start) OR p_end<>public.fn_union_week_start(p_start+interval '8 days')
  OR p_end>clock_timestamp() THEN RAISE EXCEPTION 'invalid_closed_pnl_evidence_period' USING ERRCODE='22023'; END IF;
 SELECT captured_at INTO v_fence FROM public.union_pnl_weekly_capture WHERE singleton;
 IF v_fence IS NULL OR p_start<=v_fence THEN
  RETURN jsonb_build_object('report_version',1,'status','blocked','basis_certified',false,'payment_authorized',false,
   'issues',jsonb_build_array('week_precedes_complete_original_capture'),'capture_started_at',v_fence,'all_players_included',false);
 END IF;
 IF p_union_id='fade0000-0000-0000-0000-000000000001'::uuid AND p_end>='2026-10-12 07:00:00Z'::timestamptz THEN
  v_generation:=COALESCE(smarter_private.original_inventory_basis_generation(),'original-inventory-245:unqualified');
 END IF;
 -- UNION P&L EVIDENCE MEMO (20260928): one weekly close reaches this report
 -- through preparation (close quality), the cascade (qualified clubs, ECO,
 -- player P&L) and the invoices. Inside a union close attempt
 -- (app.accounting_close_memo='on', set only by fn_weekly_accounting_attempt_begin)
 -- the first complete report of this (union, week) is kept for the rest of
 -- the attempt; attempt_begin and attempt_end clear it and a rolled-back
 -- subtransaction forgets it with its settings. Everywhere else the report is
 -- proved on every call, exactly as before.
 IF current_setting('app.accounting_close_memo',true)='on' THEN
  v_memo_key:=CASE WHEN v_generation='original-inventory-245:unqualified' THEN NULL ELSE COALESCE(v_generation||'|','')||p_union_id::text||'|'||p_start::text||'|'||p_end::text END;
  v_memo:=NULLIF(current_setting('app.union_pnl_evidence_memo',true),'')::jsonb;
  IF v_memo ? v_memo_key THEN RETURN v_memo->v_memo_key; END IF;
 END IF;
 -- UNION P&L NARROW READS (20260929044303): the week's registration events,
 -- hands and tournament credits are read through their narrow projections
 -- (union_pnl_inventory_touches, union_pnl_cash_outcome_touches,
 -- union_pnl_credit_touches), each written by its source row's own insert,
 -- once the throttled backfill has proved it complete; until then through
 -- the original wide rows, statement for statement as before.
 v_inv:=public.fn_union_pnl_projection_ready('inventory_touches');
 v_cash:=public.fn_union_pnl_projection_ready('cash_outcome_touches');
 v_credit:=public.fn_union_pnl_projection_ready('credit_touches');
 -- Both readers wait for the original book's in-flight transactions; this
 -- function is VOLATILE so every subsequent query sees their committed facts.
 -- CHUNKED CLOSE CERTIFICATES (20261003): inside a chunked union close attempt
 -- each expensive read below that found nothing wrong is kept, once proved,
 -- in accounting_close_certificates for the rest of that close of this
 -- closed week (fn_accounting_close_certificate / fn_accounting_close_certify;
 -- both do nothing anywhere else). An attempt whose time budget is spent
 -- after a step it had to prove returns 'warming' - not ready, nothing
 -- certified for payment - and the next attempt continues from the kept
 -- steps. A step that found a problem is kept for ONE HOUR (20261012), as
 -- '<kind>_problem' (fn_accounting_close_problem): it is never certified and
 -- never pays, its issues are reported exactly as before, and an attempt
 -- re-proves it once that hour has passed. Re-proving every problem step on
 -- every attempt is what held job 272's transactions for 3 to 5 minutes.
 v_open:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_boundary',p_union_id,p_start,p_start),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_boundary',p_union_id,p_start,p_start));
 IF v_open IS NULL THEN
  v_open:=public.fn_union_pnl_boundary(p_union_id,p_start);
  IF v_open->>'status'='ready' THEN PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_boundary',p_union_id,p_start,p_start,v_open);
  ELSE PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_boundary_problem',p_union_id,p_start,p_start,v_open); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 -- THE WINDOWS GO FIRST (20261012): the plan's two-hour windows (seconds each)
 -- are proved before the steps below, so an attempt that would otherwise
 -- spend its budget re-reading the boundaries and flows proves windows
 -- instead. Outside a chunked close the advance is NULL and nothing changes.
 IF public.fn_accounting_union_earned_plan_advance(p_union_id,p_start,p_end) IS FALSE THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 v_close:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_boundary',p_union_id,p_end,p_end),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_boundary',p_union_id,p_end,p_end));
 IF v_close IS NULL THEN
  v_close:=public.fn_union_pnl_boundary(p_union_id,p_end);
  IF v_close->>'status'='ready' THEN PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_boundary',p_union_id,p_end,p_end,v_close);
  ELSE PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_boundary_problem',p_union_id,p_end,p_end,v_close); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 IF v_open->>'status' IS DISTINCT FROM 'ready' THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','opening_basis_incomplete','evidence',v_open)); END IF;
 IF v_close->>'status' IS DISTINCT FROM 'ready' THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','closing_basis_incomplete','evidence',v_close)); END IF;
 -- The registrations the opening boundary carried through a valid opening
 -- resolution (union_pnl_opening_registration_resolutions): each one's
 -- original entry is proved from the posted chip ledger, not a funding receipt.
 v_open_resolved:=ARRAY(SELECT (x->>'source_id')::uuid FROM jsonb_array_elements(COALESCE(v_open->'holdings','[]')) x
  WHERE x->>'kind'='deferred_tournament_result' AND x->>'basis'='opening_registration_resolution');
 -- A blocked outcome counts as accepted only through an immutable resolution
 -- receipt re-proved from primary receipts and bound to this exact outcome
 -- (hand, payload hash, evidence). The outcome row itself is never changed.
 -- Only a hand outside the ready/certified/all-players/same-scope shape can
 -- be refused or resolved: those hands (the predicate of
 -- union_pnl_cash_outcomes_unaccepted), found through the projection's shape
 -- flag and re-checked against their rows, never the whole week's evidence.
 SELECT count(*) FILTER(WHERE NOT public.fn_union_pnl_cash_outcome_accepted(o)),
  count(*) FILTER(WHERE (o.evidence->>'status' IS DISTINCT FROM 'ready' OR o.evidence->'basis_certified' IS DISTINCT FROM 'true'::jsonb)
   AND public.fn_union_pnl_cash_outcome_accepted(o))
 INTO v_bad,v_resolved FROM public.fn_union_pnl_week_shaped_hands(p_union_id,p_start,p_end,v_cash) o;
 -- A hand whose provenance link the engine never recorded (its outcome has no
 -- game scope) counts only through its immutable link resolution
 -- (union_pnl_cash_outcome_link_resolutions), in the Union its re-proved scope
 -- names, and is accepted only when its re-proved evidence is certified.
 SELECT v_bad+count(*) FILTER(WHERE NOT (k.evidence->>'status'='ready' AND k.evidence->'basis_certified'='true'::jsonb
   AND k.evidence->'all_players_included'='true'::jsonb)),
  v_resolved+count(*) FILTER(WHERE k.evidence->>'status'='ready' AND k.evidence->'basis_certified'='true'::jsonb
   AND k.evidence->'all_players_included'='true'::jsonb)
 INTO v_bad,v_resolved FROM public.fn_union_pnl_linked_cash_outcomes(p_union_id,p_start,p_end) k;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','accepted_cash_basis_incomplete','count',v_bad)); END IF;
 -- A missing original game scope cannot silently disappear from every Union.
 SELECT count(*) INTO v_bad FROM public.union_pnl_cash_outcomes WHERE recognized_at>=p_start AND recognized_at<p_end
  AND NOT game_scope ?& ARRAY['game_union_id','host_club_id','tournament_id','is_private','asset','unit_scale']
  AND NOT EXISTS(SELECT 1 FROM public.fn_union_pnl_cash_outcome_link(union_pnl_cash_outcomes));
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','accepted_cash_original_scope_missing','count',v_bad)); END IF;
 SELECT count(*) INTO v_bad FROM public.union_pnl_original_flows WHERE recognized_at>=p_start AND recognized_at<p_end
  AND NOT game_scope ?& ARRAY['game_union_id','host_club_id','tournament_id','is_private','asset','unit_scale'];
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','original_money_flow_scope_missing','count',v_bad)); END IF;
 SELECT count(*) INTO v_bad FROM public.cash_participant_funding_receipts WHERE recorded_at>=v_fence AND recorded_at<p_end AND transaction_id IS NULL;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array('post_capture_funding_transaction_identity_missing'); END IF;
 SELECT count(*) INTO v_bad FROM public.cash_funding_application_receipts WHERE applied_at>=v_fence AND applied_at<p_end AND transaction_id IS NULL;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array('post_capture_application_transaction_identity_missing'); END IF;
 SELECT count(*) INTO v_bad FROM public.cash_hand_provenance_receipts WHERE accepted_at>=v_fence AND accepted_at<p_end AND transaction_id IS NULL;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array('post_capture_hand_transaction_identity_missing'); END IF;
 -- The flow proof is read once; the P&L below reuses these exact rows.
 v_cert:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_flows',p_union_id,p_start,p_end),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_flows',p_union_id,p_start,p_end));
 IF v_cert IS NOT NULL THEN
  v_bad:=(v_cert->>'bad')::bigint; v_flows:=v_cert->'flows';
 ELSE
 SELECT count(*) FILTER(WHERE NOT f.valid),COALESCE(jsonb_agg(to_jsonb(f)),'[]') INTO v_bad,v_flows
  FROM public.fn_union_pnl_original_flow_evidence(p_union_id,p_start,p_end) f;
  IF v_bad=0 THEN PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_flows',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad,'flows',v_flows));
  ELSE PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_flows_problem',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad,'flows',v_flows)); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','original_money_flow_basis_incomplete','count',v_bad)); END IF;
 -- Every touched tournament registration must have its original chip entry,
 -- including zero-rake players. Historical/current membership is never used.
 -- The week's registration events, each touched tournament's Union proved
 -- once through its own events (t.row_id::text equality kept; the uuid
 -- equality only lets the index find the same rows and is never attempted on
 -- a non-canonical id). The frame test is unchanged; i.observed_at repeats it
 -- because fn_union_pnl_inventory_observe, the only writer of framed events,
 -- stamps each event with its frame's observed_at (both tables immutable), so
 -- the same rows are reached through union_pnl_inventory_events_players_observed.
 -- Both reads (fn_union_pnl_touched_registrations, fn_union_pnl_tournament_in_union)
 -- come from union_pnl_inventory_touches once it is complete: the same keys,
 -- the frame's observed_at copied at capture, without the wide rows.
 v_cert:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_touched',p_union_id,p_start,p_end),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_touched',p_union_id,p_start,p_end));
 IF v_cert IS NOT NULL THEN
  v_bad:=(v_cert->>'bad')::bigint;
 ELSE
 WITH touched AS MATERIALIZED (
  SELECT w.registration_id row_id,w.touched_tournament_id tournament_id
  FROM public.fn_union_pnl_touched_registrations(p_start,p_end,v_inv) w
 ), union_tournaments AS MATERIALIZED (
  SELECT d.tournament_id FROM (SELECT DISTINCT tournament_id FROM touched) d
  WHERE public.fn_union_pnl_tournament_in_union(d.tournament_id,p_union_id,v_inv)
 ), union_touched AS MATERIALIZED (
  SELECT i.row_id FROM touched i WHERE i.tournament_id IN (SELECT tournament_id FROM union_tournaments)
 ), entries AS MATERIALIZED (
  -- the two receipt tests, read once per touched registration (column for
  -- column: a whole-row argument would detoast every receipt's snapshots)
  SELECT r.registration_id,
   bool_or(r.asset='chips' AND public.fn_union_pnl_tournament_entry_club_of(r.asset,r.amount,r.funding_club_id,r.ledger_id,r.entitlement_id,r.registration_snapshot) IS NOT NULL) has_entry,
   bool_or(r.asset<>'chips' OR public.fn_union_pnl_tournament_entry_club_of(r.asset,r.amount,r.funding_club_id,r.ledger_id,r.entitlement_id,r.registration_snapshot) IS NULL) has_other
  FROM public.tournament_participant_funding_receipts r
  WHERE r.registration_id IN (SELECT row_id FROM union_touched)
  GROUP BY r.registration_id
 ) SELECT count(*) INTO v_bad FROM union_touched i LEFT JOIN entries e ON e.registration_id=i.row_id
 WHERE (NOT COALESCE(e.has_entry,false) AND i.row_id<>ALL(v_open_resolved)
   AND public.fn_union_pnl_satellite_seat_owner(i.row_id,NULL) IS NULL)
  OR COALESCE(e.has_other,false);
  IF v_bad=0 THEN PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_touched',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad));
  ELSE PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_touched_problem',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad)); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','tournament_original_population_or_instrument_incomplete','count',v_bad)); END IF;
 -- An award must return to the original funding club; a changed credited
 -- wallet does not prove a new earning ownership agreement.
 -- The week's credits of this Union (its tournament snapshot's Union, its
 -- frame in the week) come from union_pnl_credit_touches once complete. The
 -- two whole-row resolutions (a whole-row value detoasts every snapshot of
 -- the credit) are asked only of a credit the entry test did not settle: the
 -- same conjunction, in an order the planner may not change.
 SELECT count(*) INTO v_bad FROM public.fn_union_pnl_week_union_credits(p_union_id,p_start,p_end,v_credit) w
 JOIN public.tournament_accounting_credit_receipts c ON c.id=w.credit_id
 WHERE CASE WHEN (cardinality(c.entry_receipt_ids)=0 OR EXISTS(SELECT 1 FROM unnest(c.entry_receipt_ids) original_id(receipt_id)
   LEFT JOIN public.tournament_participant_funding_receipts r ON r.id=original_id.receipt_id
   WHERE r.id IS NULL OR r.asset<>'chips' OR public.fn_union_pnl_tournament_entry_club_of(r.asset,r.amount,r.funding_club_id,r.ledger_id,r.entitlement_id,r.registration_snapshot) IS DISTINCT FROM c.credited_club_id OR r.user_id IS DISTINCT FROM c.user_id))
  THEN NOT public.fn_union_pnl_award_owner_resolved(c,p_union_id,p_start,v_open_resolved)
   AND NOT public.fn_union_pnl_award_satellite_owner(c) ELSE false END;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','tournament_award_original_earning_owner_incomplete','count',v_bad)); END IF;
 v_eco:=public.fn_union_eco_terms_evidence(p_union_id,p_start,p_end);
 IF v_eco->>'status' IS DISTINCT FROM 'ready' THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','eco_commercial_basis_incomplete','evidence',v_eco)); END IF;
 SELECT count(DISTINCT x->'terms') INTO v_bad FROM jsonb_array_elements(COALESCE(v_eco->'segments','[]')) x;
 IF v_bad<>1 THEN v_issues:=v_issues||jsonb_build_array('eco_intraweek_changed_terms_require_original_allocation'); END IF;
 v_terms_value:=v_eco#>'{segments,0,terms}';
 -- Validate every original bank/source leg even when the week has no rows.
 -- CHUNKED CLOSE WINDOWS (20261003): inside a chunked close the plan's
 -- two-hour windows are proved first, a few per attempt; until all are, the
 -- attempt stops warming (fn_accounting_union_earned_plan_advance is NULL,
 -- and this test passes, everywhere else).
 -- (THE WINDOWS GO FIRST, 20261012: the plan's windows are proved above,
 -- right after the opening boundary, before any step that can be re-proved.)
 PERFORM public.fn_accounting_union_earned_plan(p_union_id,p_start,p_end);
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 v_cert:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_clubs',p_union_id,p_start,p_end),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_clubs',p_union_id,p_start,p_end));
 IF v_cert IS NOT NULL THEN
  v_clubs:=v_cert->'clubs'; v_cash_reconciled:=(v_cert->>'cash_reconciled')::boolean; v_rows:=(v_cert->>'rows')::bigint;
  v_cash_rake:=(v_cert->>'cash_rake')::numeric; v_hands:=(v_cert->>'hands')::bigint; v_accepted_rake:=(v_cert->>'accepted_rake')::numeric;
 ELSE
 WITH flows AS MATERIALIZED (SELECT * FROM jsonb_to_recordset(v_flows)
  AS f(ledger_id uuid,club_id uuid,user_id uuid,buyins numeric,cashouts numeric,kind text,valid boolean)),
 -- One read of the week's hands: each (club, player) delta total, and (kind 0)
 -- the hand count and accepted rake that used to cost two more reads.
 outcome_pass AS MATERIALIZED (
  SELECT x.kind,x.club_id,x.user_id,sum(x.delta) delta,count(*) hands,sum(x.rake) rake
  FROM (SELECT h.hand_accepted_rake accepted_rake,h.hand_participants participants
   FROM public.fn_union_pnl_week_hand_lines(p_union_id,p_start,p_end,v_cash) h
   -- with this Union's linked hands, through their link resolutions
   UNION ALL SELECT k.evidence->>'accepted_rake',k.evidence->'participants' FROM public.fn_union_pnl_linked_cash_outcomes(p_union_id,p_start,p_end) k) o CROSS JOIN LATERAL (
   SELECT 0 kind,NULL::uuid club_id,NULL::uuid user_id,NULL::numeric delta,o.accepted_rake::numeric rake
   UNION ALL
   SELECT 1,(p->>'earning_club_id')::uuid,(p->>'user_id')::uuid,(p->>'observed_stack_delta')::numeric,NULL::numeric
   FROM jsonb_array_elements(COALESCE(o.participants,'[]')) p) x
  GROUP BY x.kind,x.club_id,x.user_id
 ), hand_players AS (SELECT club_id,user_id,delta FROM outcome_pass WHERE kind=1
  -- JACKPOT SHARES ON THE FELT (20260929): a Bad Beat Jackpot share credited
  -- to a seat after its hand committed is that player's cash result too.
  UNION ALL SELECT a.club_id,a.user_id,a.amount FROM public.fn_union_pnl_week_bbj_stack_awards(p_union_id,p_start,p_end) a), opening AS (SELECT (x->>'club_id')::uuid club_id,sum((x->>'amount')::numeric) amount,
   sum((x->>'amount')::numeric) FILTER(WHERE x->>'kind'<>'deferred_tournament_result') cash
   FROM jsonb_array_elements(COALESCE(v_open->'holdings','[]')) x GROUP BY 1),
 closing AS (SELECT (x->>'club_id')::uuid club_id,sum((x->>'amount')::numeric) amount,
   sum((x->>'amount')::numeric) FILTER(WHERE x->>'kind'<>'deferred_tournament_result') cash
   FROM jsonb_array_elements(COALESCE(v_close->'holdings','[]')) x GROUP BY 1),
 -- The canonical payout basis excludes retained Union-house rake. Gross
 -- original rake still belongs in the all-player P&L and bank reconciliation.
 rake AS MATERIALIZED (
  SELECT s.club_id,sum(s.rake_credit) generated,COALESCE(k.earned,0) earned,
   sum(s.rake_credit) FILTER(WHERE s.source_type='cash_rake_accrual') cash_rake,
   sum(s.rake_credit) FILTER(WHERE s.source_type='tournament_fee_accrual') tournament_rake
  FROM public.accounting_payable_earning_sources s
  LEFT JOIN (SELECT club_id,sum(payout) earned FROM public.fn_union_club_rake_basis(p_union_id,p_start,p_end) GROUP BY club_id) k ON k.club_id=s.club_id
  WHERE s.union_id=p_union_id AND s.earned_at>=p_start AND s.earned_at<p_end GROUP BY s.club_id,k.earned
 ),
 roster AS (
  SELECT DISTINCT (COALESCE(after_row,before_row)->>'club_id')::uuid club_id FROM public.union_pnl_inventory_events
   WHERE source_name='union_clubs' AND COALESCE(after_row,before_row)->>'union_id'=p_union_id::text AND observed_at<p_end
    AND (observed_at>=p_start OR row_id::text IN(SELECT x#>>'{row,id}' FROM jsonb_array_elements(COALESCE(v_open#>'{inventory,population,union_clubs}','[]')) x))
  UNION SELECT club_id FROM rake UNION SELECT club_id FROM flows UNION SELECT club_id FROM hand_players UNION SELECT club_id FROM opening UNION SELECT club_id FROM closing
 ), movement AS (SELECT club_id,sum(buyins) buyins,sum(cashouts) cashouts,
  sum(cashouts-buyins) FILTER(WHERE kind IN('cash_funding','cash_return','cash_late_settlement')) cash_flow,
  sum(buyins) FILTER(WHERE kind='cash_funding') cash_buyins,sum(cashouts) FILTER(WHERE kind='cash_return') cash_cashouts FROM flows GROUP BY club_id),
 hands AS (SELECT club_id,sum(delta) delta FROM hand_players GROUP BY club_id),
 people AS (SELECT club_id,count(DISTINCT user_id)::int players FROM(SELECT club_id,user_id FROM flows UNION SELECT club_id,user_id FROM hand_players
  UNION SELECT (x->>'club_id')::uuid,(x->>'user_id')::uuid FROM jsonb_array_elements(COALESCE(v_open->'holdings','[]')||COALESCE(v_close->'holdings','[]')) x) q GROUP BY club_id),
 club_rows AS (
  SELECT r.club_id,COALESCE(m.buyins,0) buyins,COALESCE(m.cashouts,0) cashouts,COALESCE(m.cash_buyins,0) cash_buyins,COALESCE(m.cash_cashouts,0) cash_cashouts,
   COALESCE(m.cashouts,0)-COALESCE(m.buyins,0) realized_net,COALESCE(o.amount,0) seated_start,COALESCE(c.amount,0) seated_end,
   COALESCE(o.cash,0) seated_start_cash,COALESCE(c.cash,0) seated_end_cash,
   COALESCE(c.amount,0)-COALESCE(o.amount,0) stack_delta,COALESCE(h.delta,0) cash_player_pnl,
   COALESCE(m.cashouts,0)-COALESCE(m.buyins,0)+COALESCE(c.amount,0)-COALESCE(o.amount,0)-COALESCE(h.delta,0) tournament_player_pnl,
   COALESCE(m.cash_flow,0)+COALESCE(c.cash,0)-COALESCE(o.cash,0)=COALESCE(h.delta,0) cash_reconciled,
   COALESCE(p.players,0) players,COALESCE(k.generated,0) rake_paid,COALESCE(k.earned,0) rake_earned,COALESCE(k.cash_rake,0) cash_rake,COALESCE(k.tournament_rake,0) tournament_rake,
   COALESCE(m.cashouts,0)-COALESCE(m.buyins,0)+COALESCE(c.amount,0)-COALESCE(o.amount,0)+COALESCE(k.generated,0) net
  FROM roster r LEFT JOIN movement m USING(club_id) LEFT JOIN opening o USING(club_id) LEFT JOIN closing c USING(club_id)
  LEFT JOIN hands h USING(club_id) LEFT JOIN people p USING(club_id) LEFT JOIN rake k USING(club_id)
  WHERE r.club_id IS NOT NULL
 ), player_results AS (
  SELECT club_id,user_id,sum(delta) delta FROM (
   SELECT club_id,user_id,cashouts-buyins delta FROM flows
   UNION ALL SELECT (x->>'club_id')::uuid,(x->>'user_id')::uuid,(x->>'amount')::numeric FROM jsonb_array_elements(COALESCE(v_close->'holdings','[]')) x
   UNION ALL SELECT (x->>'club_id')::uuid,(x->>'user_id')::uuid,-(x->>'amount')::numeric FROM jsonb_array_elements(COALESCE(v_open->'holdings','[]')) x
  ) amounts GROUP BY club_id,user_id
 ), wins AS(SELECT club_id,sum(greatest(delta,0)) winnings,sum(greatest(-delta,0)) losses FROM player_results GROUP BY club_id), complete AS (
  SELECT q.*,COALESCE(w.winnings,0) winnings,COALESCE(w.losses,0) losses,
   CASE v_terms_value->>'eco_base_mode'
    WHEN 'club_cash_profit' THEN rake_earned-cash_player_pnl
    WHEN 'net_invoice_position' THEN realized_net+stack_delta+rake_paid+rake_earned
    WHEN 'winnings_plus_rake' THEN realized_net+stack_delta+rake_paid
    WHEN 'winnings_only' THEN realized_net+stack_delta END eco_base
  FROM club_rows q LEFT JOIN wins w USING(club_id)
 ) SELECT COALESCE(jsonb_agg(to_jsonb(q)||jsonb_build_object('eco_amount',CASE WHEN v_terms_value->'eco_enabled'='true'::jsonb
  THEN round(-(v_terms_value->>'eco_rate')::numeric*eco_base,2) ELSE 0 END) ORDER BY club_id),'[]'),
  COALESCE(bool_and(cash_reconciled),true),count(*),COALESCE(sum(cash_rake),0),
  COALESCE((SELECT h.hands FROM outcome_pass h WHERE h.kind=0),0),(SELECT COALESCE(sum(h.rake),0) FROM outcome_pass h WHERE h.kind=0)
  INTO v_clubs,v_cash_reconciled,v_rows,v_cash_rake,v_hands,v_accepted_rake FROM complete q;
  IF v_cash_reconciled AND v_accepted_rake IS NOT DISTINCT FROM v_cash_rake THEN
   PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_clubs',p_union_id,p_start,p_end,jsonb_build_object('clubs',v_clubs,
    'cash_reconciled',v_cash_reconciled,'rows',v_rows,'cash_rake',v_cash_rake,'hands',v_hands,'accepted_rake',v_accepted_rake));
  ELSE
   PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_clubs_problem',p_union_id,p_start,p_end,jsonb_build_object('clubs',v_clubs,
    'cash_reconciled',v_cash_reconciled,'rows',v_rows,'cash_rake',v_cash_rake,'hands',v_hands,'accepted_rake',v_accepted_rake));
  END IF;
 END IF;
 IF v_accepted_rake IS DISTINCT FROM v_cash_rake THEN v_issues:=v_issues||jsonb_build_array('accepted_cash_rake_does_not_match_original_earning_and_bank_basis'); END IF;
 IF NOT v_cash_reconciled THEN v_issues:=v_issues||jsonb_build_array('accepted_cash_deltas_do_not_reconcile_original_flows_and_boundaries'); END IF;
 v_report:=jsonb_build_object('report_version',1,'status',CASE WHEN v_issues='[]'::jsonb THEN 'ready' ELSE 'blocked' END,
  'basis_certified',v_issues='[]'::jsonb,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,
  'issues',v_issues,'clubs',v_clubs,'opening_basis',v_open,'closing_basis',v_close,'eco_commercial_terms_evidence',v_eco,
  'accepted_cash_hands',v_hands,'accepted_cash_hands_resolved',v_resolved,'club_count',v_rows,'current_seats_used',false,'current_membership_used',false,
  'all_players_included',v_issues='[]'::jsonb,'tournament_basis','original_realized_settlement_deferred_while_open');
 IF v_memo_key IS NOT NULL THEN
  PERFORM set_config('app.union_pnl_evidence_memo',(COALESCE(NULLIF(current_setting('app.union_pnl_evidence_memo',true),'')::jsonb,'{}')
   ||jsonb_build_object(v_memo_key,v_report))::text,true);
 END IF;
 RETURN v_report;
END $function$

CREATE OR REPLACE FUNCTION public.fn_union_pnl_inventory_as_of(p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE origin public.union_pnl_inventory_capture%ROWTYPE; book timestamptz; v_base timestamptz; v_projection jsonb; v_result jsonb;
BEGIN
 SELECT * INTO origin FROM public.union_pnl_inventory_capture WHERE singleton;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','blocked','reason','inventory_capture_missing'); END IF;
 IF p_at IS NULL OR NOT isfinite(p_at) OR p_at<>public.fn_union_week_start(p_at) OR p_at>clock_timestamp() THEN
  RETURN jsonb_build_object('status','blocked','reason','closed_original_week_boundary_required'); END IF;
 IF p_at<=origin.captured_at THEN RETURN jsonb_build_object('status','blocked','reason','boundary_precedes_original_inventory_capture','capture_started_at',origin.captured_at); END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RETURN jsonb_build_object('status','blocked','reason','inventory_requires_fresh_read_committed_snapshot'); END IF;
 book:=public.fn_union_week_start(origin.captured_at);
 WHILE book<p_at LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('union-pnl-inventory:'||extract(epoch FROM book)::bigint::text,0));
  book:=public.fn_union_week_start(book+interval '8 days');
 END LOOP;
 -- Every writer that could precede p_at has committed (the locks above), so
 -- the result is final: one transaction computes it once.
 IF to_regclass('pg_temp.union_pnl_inventory_as_of_cache') IS NOT NULL THEN
  EXECUTE 'SELECT result FROM pg_temp.union_pnl_inventory_as_of_cache WHERE boundary=$1' INTO v_result USING p_at;
  IF v_result IS NOT NULL THEN RETURN v_result; END IF;
 END IF;
 -- VOLATILE intentionally obtains a fresh snapshot after the old-book writers
 -- have committed. A stable/snapshot reader could omit those committed events.
 SELECT c.boundary INTO v_base FROM public.union_pnl_inventory_checkpoints c WHERE c.boundary<=p_at ORDER BY c.boundary DESC LIMIT 1;
 v_projection:=public.fn_union_pnl_inventory_population(v_base,p_at);
 v_result:=jsonb_build_object('status',CASE WHEN v_projection->'issues'='[]'::jsonb THEN 'observed' ELSE 'blocked' END,
  'inventory_version',1,'capture_started_at',origin.captured_at,'boundary',p_at,'population',v_projection->'population','issues',v_projection->'issues',
  'current_state_used',false,'financial_basis_certified',false,
  'coverage','Original active population and later captured transitions; monetary funding and obligation receipts must independently certify equity.');
 BEGIN
  IF to_regclass('pg_temp.union_pnl_inventory_as_of_cache') IS NULL THEN
   EXECUTE 'CREATE TEMP TABLE union_pnl_inventory_as_of_cache(boundary timestamptz PRIMARY KEY, result jsonb NOT NULL) ON COMMIT DROP';
  END IF;
  EXECUTE 'INSERT INTO pg_temp.union_pnl_inventory_as_of_cache(boundary,result) VALUES($1,$2) ON CONFLICT (boundary) DO NOTHING' USING p_at,v_result;
 EXCEPTION WHEN read_only_sql_transaction THEN NULL;
 END;
 RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION smarter_private.certify_original_inventory_restoration(p_event_id bigint, p_boundary timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE expected text; family text; witness jsonb; proof jsonb;
BEGIN
 IF session_user IS DISTINCT FROM 'postgres' OR current_user IS DISTINCT FROM 'postgres'
 OR nullif(current_setting('request.jwt.claim.role',true),'') IS NOT NULL THEN
  RAISE EXCEPTION 'original_inventory_certificate_caller_refused' USING ERRCODE='42501';END IF;
 IF p_event_id IS NULL OR p_boundary IS DISTINCT FROM '2026-10-12 07:00:00Z'::timestamptz
 OR public.fn_platform_frozen() IS DISTINCT FROM false
 OR smarter_private.original_inventory_proof_sources_match() IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'original_inventory_certificate_boundary_refused' USING ERRCODE='55000';END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('union-pnl-original-inventory-restoration',0)) THEN
  RAISE EXCEPTION 'original_inventory_certificate_writer_busy' USING ERRCODE='55000';END IF;
 SELECT witness_md5,k.family INTO expected,family FROM smarter_private.original_inventory_restoration_cases k WHERE event_id=p_event_id;
 IF expected IS NULL OR EXISTS(SELECT 1 FROM smarter_private.original_inventory_restoration_certificates
 WHERE event_id=p_event_id AND boundary=p_boundary) THEN
  RAISE EXCEPTION 'original_inventory_certificate_unknown_or_replayed' USING ERRCODE='55000';END IF;
 witness:=smarter_private.original_inventory_finite_witness(p_event_id);
 IF witness IS NULL OR md5(witness::text) IS DISTINCT FROM expected THEN
  RAISE EXCEPTION 'original_inventory_certificate_witness_changed' USING ERRCODE='55000';END IF;
 proof:=smarter_private.original_inventory_finite_family_proof(family,witness,'2026-10-05 07:00:00Z',p_boundary);
 IF proof->>'status' IS DISTINCT FROM 'ready' OR proof->'financial_admission' IS DISTINCT FROM 'false'::jsonb THEN
  RAISE EXCEPTION 'original_inventory_certificate_proof_refused' USING ERRCODE='55000';END IF;
 INSERT INTO smarter_private.original_inventory_restoration_certificates(event_id,boundary,witness_md5,original_witness,proof,proof_md5)
 VALUES(p_event_id,p_boundary,expected,witness,proof,md5(proof::text));
 RETURN jsonb_build_object('original_inventory_certificate',true,'event_id',p_event_id,'boundary',p_boundary,
  'witness_md5',expected,'proof_md5',md5(proof::text),'financial_payment',false);
END $function$

CREATE OR REPLACE FUNCTION smarter_private.inventory_basis_cache_read(p_generation text, p_problem boolean, p_kind text, p_union uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE v jsonb;
BEGIN
 IF p_generation='original-inventory-245:unqualified' THEN RETURN NULL;END IF;
 IF p_problem IS NULL OR p_kind NOT IN('pnl_boundary','pnl_flows','pnl_touched','pnl_clubs') OR p_kind IS NULL THEN RETURN NULL;END IF;
 IF p_problem THEN v:=public.fn_accounting_close_problem(p_kind,p_union,p_start,p_end);
 ELSE v:=public.fn_accounting_close_certificate(p_kind,p_union,p_start,p_end);END IF;
 IF p_generation IS NULL THEN RETURN v;END IF;
 IF v IS NULL OR v->>'_original_inventory_generation' IS DISTINCT FROM p_generation THEN RETURN NULL;END IF;
 RETURN v-'_original_inventory_generation';
END $function$

CREATE OR REPLACE FUNCTION smarter_private.inventory_restoration_issue_accepted(issue jsonb, p_boundary timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE event bigint; witness jsonb; proof jsonb; c record;
BEGIN
 IF jsonb_typeof(issue) IS DISTINCT FROM 'object' OR issue->>'reason' IS DISTINCT FROM 'original_inventory_chain_disagrees'
 OR issue->>'source_name' NOT IN('tournament_players','table_seats') OR issue->>'source_name' IS NULL
 OR issue->>'source_event_id' IS NULL OR issue->>'source_event_id' !~ '^[0-9]+$'
 OR p_boundary IS NULL OR NOT isfinite(p_boundary) OR p_boundary<'2026-10-12 07:00:00Z'::timestamptz THEN RETURN false;END IF;
 IF smarter_private.original_inventory_proof_sources_match() IS DISTINCT FROM true THEN RETURN false;END IF;
 event:=(issue->>'source_event_id')::bigint;
 SELECT r.*,k.source_name,k.row_id,k.family,k.witness_md5 expected_md5 INTO c
 FROM smarter_private.original_inventory_restoration_certificates r
 JOIN smarter_private.original_inventory_restoration_cases k USING(event_id)
 WHERE r.event_id=event AND r.boundary='2026-10-12 07:00:00Z'::timestamptz;
 IF NOT FOUND OR issue->>'row_id' IS DISTINCT FROM c.row_id::text
 OR issue->>'source_name' IS DISTINCT FROM c.source_name OR c.witness_md5 IS DISTINCT FROM c.expected_md5
 OR c.witness_md5 IS DISTINCT FROM md5(c.original_witness::text) OR c.proof_md5 IS DISTINCT FROM md5(c.proof::text) THEN RETURN false;END IF;
 witness:=smarter_private.original_inventory_finite_witness(event);
 IF witness IS NULL OR md5(witness::text) IS DISTINCT FROM c.expected_md5 THEN RETURN false;END IF;
 proof:=smarter_private.original_inventory_finite_family_proof(c.family,witness,'2026-10-05 07:00:00Z','2026-10-12 07:00:00Z');
 RETURN proof->>'status'='ready' AND proof->'financial_admission'='false'::jsonb
  AND proof IS NOT DISTINCT FROM c.proof AND md5(proof::text)=c.proof_md5;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION smarter_private.original_erased_cash_base_discharge_evidence_valid(e bigint, h text, s jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE r jsonb;f jsonb;p jsonb;k text;u uuid;club uuid;occ uuid;tbl uuid;a numeric;
 mt record;il record;cl record;bt record;ct record;ik record;refs jsonb;at_time timestamptz;n integer;
BEGIN
 IF s IS NULL OR jsonb_typeof(s) IS DISTINCT FROM 'object' OR NOT(s ?& ARRAY['status','event_id','custody','occupancy_id','user_id','funding_club_id','base_cents','amount','restoration_key','discharged_at','mint_id','issuance_leg_id','base_credit_transaction_id','bank_claim_leg_id','bank_claim_transaction_id','bank_claim_operation_id','final_player_wallet','bank_increment','bank_before','bank_after','bank_owner_id','preserved_played_delta','financial_refs']) OR s-ARRAY['status','event_id','custody','occupancy_id','user_id','funding_club_id','base_cents','amount','restoration_key','discharged_at','mint_id','issuance_leg_id','base_credit_transaction_id','bank_claim_leg_id','bank_claim_transaction_id','bank_claim_operation_id','final_player_wallet','bank_increment','bank_before','bank_after','bank_owner_id','preserved_played_delta','financial_refs'] IS DISTINCT FROM '{}'::jsonb OR h IS NULL
 OR h IS DISTINCT FROM smarter_private.original_erased_cash_base_expected_hash(e) THEN RETURN false;END IF;
 r:=smarter_private.original_erased_cash_base_request(e,h);
 IF r->>'status' IS DISTINCT FROM 'ready' OR r->'financial_admission' IS DISTINCT FROM 'false'::jsonb
 OR r->>'witness_md5' IS DISTINCT FROM h OR md5((r->'witness')::text) IS DISTINCT FROM h THEN RETURN false;END IF;
 f:=r->'witness';p:=smarter_private.original_erased_cash_base_proof(f,'2026-10-12 07:00Z');
 IF p IS DISTINCT FROM r->'proof' OR p->>'status' IS DISTINCT FROM 'ready' THEN RETURN false;END IF;
 u:=(p#>>'{holding,user_id}')::uuid;club:=(p#>>'{holding,club_id}')::uuid;
 occ:=(f#>>'{signed,occupancy_id}')::uuid;tbl:=(f#>>'{event,before_row,table_id}')::uuid;
 a:=(p->>'original_base')::numeric;k:='retired_completed_cash_base:'||occ;
 at_time:=(s->>'discharged_at')::timestamptz;
 IF at_time IS NULL OR NOT isfinite(at_time) OR at_time<='2026-10-12 07:00Z'
 OR s->>'status' IS DISTINCT FROM 'discharged' OR (s->>'event_id')::bigint IS DISTINCT FROM e
 OR s->>'custody' IS DISTINCT FROM 'canonical_deleted_account_bank'
 OR s->>'user_id' IS DISTINCT FROM u::text OR s->>'funding_club_id' IS DISTINCT FROM club::text
 OR s->>'occupancy_id' IS DISTINCT FROM occ::text OR s->>'restoration_key' IS DISTINCT FROM k
 OR (s->>'base_cents')::bigint IS DISTINCT FROM (a*100)::bigint
 OR (s->>'amount')::numeric IS DISTINCT FROM a OR (s->>'bank_increment')::numeric IS DISTINCT FROM a
 OR (s->>'bank_after')::numeric-(s->>'bank_before')::numeric IS DISTINCT FROM a
 OR s->'final_player_wallet' IS DISTINCT FROM '0'::jsonb
 OR s->'preserved_played_delta' IS DISTINCT FROM p->'preserved_played_delta' THEN RETURN false;END IF;
 SELECT count(*) INTO n FROM public.ca_mint_ledger WHERE op_id=k;
 IF n<>1 THEN RETURN false;END IF;
 SELECT * INTO mt FROM public.ca_mint_ledger WHERE op_id=k;
 SELECT count(*) INTO n FROM public.chip_ledger WHERE idempotency_key=k;
 IF n<>1 THEN RETURN false;END IF;
 SELECT * INTO il FROM public.chip_ledger WHERE idempotency_key=k;
 SELECT * INTO ik FROM public.wallet_credit_idempotency WHERE key=k;
 IF NOT FOUND OR ik.user_id IS DISTINCT FROM u OR ik.amount IS DISTINCT FROM a THEN RETURN false;END IF;
 SELECT * INTO ct FROM public.chip_transactions WHERE id=(s->>'base_credit_transaction_id')::uuid;
 IF NOT FOUND THEN RETURN false;END IF;
 SELECT * INTO bt FROM public.chip_transactions WHERE id=(s->>'bank_claim_transaction_id')::uuid;
 IF NOT FOUND THEN RETURN false;END IF;
 SELECT count(*) INTO n FROM public.chip_ledger WHERE idempotency_key='deleted_account_bank_return:'||(bt.metadata->>'op_id');
 IF n<>1 THEN RETURN false;END IF;
 SELECT * INTO cl FROM public.chip_ledger WHERE idempotency_key='deleted_account_bank_return:'||(bt.metadata->>'op_id');
 IF mt.id::text IS DISTINCT FROM s->>'mint_id' OR mt.chip_ledger_id IS DISTINCT FROM il.id
 OR mt.holder_id IS DISTINCT FROM u OR mt.holder_type IS DISTINCT FROM 'player'
 OR mt.action IS DISTINCT FROM 'mint' OR mt.asset IS DISTINCT FROM 'chips' OR mt.amount IS DISTINCT FROM a
 OR mt.balance_after-mt.balance_before IS DISTINCT FROM a OR mt.created_at IS DISTINCT FROM at_time
 OR il.id::text IS DISTINCT FROM s->>'issuance_leg_id' OR il.amount IS DISTINCT FROM a
 OR il.club_id IS DISTINCT FROM club OR il.to_entity_id IS DISTINCT FROM u
 OR il.from_type IS DISTINCT FROM 'issuance_reserve' OR il.to_type IS DISTINCT FROM 'player_wallet'
 OR il.category IS DISTINCT FROM 'refund' OR il.created_at IS DISTINCT FROM at_time
 OR ct.to_user_id IS DISTINCT FROM u OR ct.club_id IS DISTINCT FROM club OR ct.table_id IS DISTINCT FROM tbl
 OR ct.amount IS DISTINCT FROM a OR ct.transaction_type IS DISTINCT FROM 'seat_credit_restored'
 OR ct.metadata->>'restore_key' IS DISTINCT FROM k OR ct.metadata->>'source' IS DISTINCT FROM 'issuance_reserve'
 OR ct.created_at IS DISTINCT FROM at_time OR ct.balance_after IS DISTINCT FROM a
 OR bt.to_user_id::text IS DISTINCT FROM s->>'bank_owner_id' OR s->>'bank_owner_id' IS NULL
 OR bt.from_user_id IS DISTINCT FROM u OR bt.club_id IS DISTINCT FROM club OR bt.amount IS DISTINCT FROM a
 OR bt.transaction_type IS DISTINCT FROM 'club_bank_claim' OR bt.created_at IS DISTINCT FROM at_time
 OR bt.metadata->>'reason' IS DISTINCT FROM 'deleted_account' OR bt.metadata->>'direction' IS DISTINCT FROM 'into_bank'
 OR bt.metadata->>'source' IS DISTINCT FROM 'player_wallet'
 OR bt.metadata->>'op_id' IS DISTINCT FROM s->>'bank_claim_operation_id'
 OR bt.balance_after IS DISTINCT FROM (s->>'bank_after')::numeric
 OR (bt.metadata->>'bank_after')::numeric IS DISTINCT FROM (s->>'bank_after')::numeric
 OR cl.id::text IS DISTINCT FROM s->>'bank_claim_leg_id' OR cl.club_id IS DISTINCT FROM club
 OR cl.from_entity_id IS DISTINCT FROM u OR cl.to_entity_id IS DISTINCT FROM club
 OR cl.from_type IS DISTINCT FROM 'player_wallet' OR cl.to_type IS DISTINCT FROM 'club_treasury'
 OR cl.amount IS DISTINCT FROM a OR cl.category IS DISTINCT FROM 'club_bank_claim'
 OR cl.correlation_id IS DISTINCT FROM (bt.metadata->>'op_id')::uuid OR cl.created_at IS DISTINCT FROM at_time
 THEN RETURN false;END IF;
 refs:=jsonb_build_array(
 jsonb_build_object('kind','wallet_credit_idempotency','id',k,'md5',md5(to_jsonb(ik)::text)),
 jsonb_build_object('kind','mint_ledger','id',k,'md5',md5(to_jsonb(mt)::text)),
 jsonb_build_object('kind','chip_ledger','id',il.id,'md5',md5(to_jsonb(il)::text)),
 jsonb_build_object('kind','chip_ledger','id',cl.id,'md5',md5(to_jsonb(cl)::text)),
 jsonb_build_object('kind','chip_transaction','id',ct.id,'md5',md5(to_jsonb(ct)::text)),
 jsonb_build_object('kind','chip_transaction','id',bt.id,'md5',md5(to_jsonb(bt)::text)));
 RETURN refs IS NOT DISTINCT FROM s->'financial_refs';
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR datetime_field_overflow THEN RETURN false;
END$function$

CREATE OR REPLACE FUNCTION smarter_private.original_erased_cash_base_discharge_receipt(e bigint, h text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE c record;r jsonb;f jsonb;p jsonb;s jsonb;v record;n integer;refs jsonb;
BEGIN
 IF h IS NULL OR h IS DISTINCT FROM smarter_private.original_erased_cash_base_expected_hash(e) THEN
 RETURN jsonb_build_object('status','blocked','reason','unknown_original_cash_discharge');END IF;
 r:=smarter_private.original_erased_cash_base_request(e,h);
 IF r->>'status' IS DISTINCT FROM 'ready' OR r->'financial_admission' IS DISTINCT FROM 'false'::jsonb
 OR r->>'witness_md5' IS DISTINCT FROM h OR md5((r->'witness')::text) IS DISTINCT FROM h
 OR md5((r->'proof')::text) IS DISTINCT FROM r->>'proof_md5' THEN
 RETURN jsonb_build_object('status','blocked','reason','original_cash_source_changed');END IF;
 f:=r->'witness';p:=r->'proof';
 SELECT * INTO c FROM smarter_private.original_erased_cash_base_discharges WHERE event_id=e;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','pending','event_id',e);END IF;
 s:=c.evidence;
 IF c.witness_md5 IS DISTINCT FROM h OR c.evidence_md5 IS DISTINCT FROM md5(s::text)
 OR c.user_id::text IS DISTINCT FROM p#>>'{holding,user_id}'
 OR c.funding_club_id::text IS DISTINCT FROM p#>>'{holding,club_id}'
 OR c.base_cents IS DISTINCT FROM ((p->>'original_base')::numeric*100)::bigint
 OR c.occupancy_id::text IS DISTINCT FROM f#>>'{signed,occupancy_id}'
 OR s->>'restoration_key' IS DISTINCT FROM c.restoration_key
 OR (s->>'discharged_at')::timestamptz IS DISTINCT FROM c.discharged_at
 OR s->>'custody' IS DISTINCT FROM 'canonical_deleted_account_bank'
 OR s->'final_player_wallet' IS DISTINCT FROM '0'::jsonb THEN
 RETURN jsonb_build_object('status','blocked','reason','original_cash_certificate_changed');END IF;
 refs:=s->'financial_refs';
 IF jsonb_typeof(refs) IS DISTINCT FROM 'array' OR jsonb_array_length(refs) IS DISTINCT FROM 6
 OR (SELECT count(DISTINCT jsonb_build_array(x->>'kind',x->>'id')) FROM jsonb_array_elements(refs)x)<>6 THEN
 RETURN jsonb_build_object('status','blocked','reason','original_cash_financial_refs_refused');END IF;
 FOR v IN SELECT value ref FROM jsonb_array_elements(refs) LOOP
 IF v.ref->>'md5' IS NULL OR v.ref->>'md5' !~ '^[0-9a-f]{32}$'
 OR smarter_private.original_inventory_source_ref_md5(v.ref) IS DISTINCT FROM v.ref->>'md5' THEN
 RETURN jsonb_build_object('status','blocked','reason','original_cash_financial_rows_changed');END IF;
 END LOOP;
 IF NOT smarter_private.original_erased_cash_base_discharge_evidence_valid(e,h,s) THEN RETURN jsonb_build_object('status','blocked','reason','original_cash_financial_association_refused');END IF;
 RETURN s||jsonb_build_object('status','discharged','event_id',e,'witness_md5',h,'evidence_md5',c.evidence_md5);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR datetime_field_overflow THEN
 RETURN jsonb_build_object('status','blocked','reason','malformed_original_cash_discharge');
END$function$

CREATE OR REPLACE FUNCTION smarter_private.original_erased_cash_base_discharge(e bigint, h text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE r jsonb;f jsonb;p jsonb;k text;u uuid;club uuid;occ uuid;tbl uuid;a numeric;
 bank_before numeric;bank_after numeric;owner_id uuid;profile_status text;member record;
 before_receipts uuid[];base_tx record;bank_tx record;issuance record;claim record;mint record;idem record;
 n integer;before_late text;after_late text;refs jsonb;s jsonb;pin record;old jsonb;
BEGIN
 IF session_user IS DISTINCT FROM 'postgres' OR current_user IS DISTINCT FROM 'postgres'
 OR nullif(current_setting('request.jwt.claim.role',true),'') IS NOT NULL
 OR nullif(current_setting('request.jwt.claims',true),'') IS NOT NULL THEN
 RAISE EXCEPTION 'original_cash_discharge_caller_refused' USING ERRCODE='42501';END IF;
 IF h IS NULL OR h IS DISTINCT FROM smarter_private.original_erased_cash_base_expected_hash(e) THEN
 RAISE EXCEPTION 'original_cash_discharge_unknown_request' USING ERRCODE='55000';END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('original-seven-cash-discharge',0)) THEN
 RAISE EXCEPTION 'original_cash_discharge_writer_busy' USING ERRCODE='55000';END IF;
 -- Exact current producer contract. Getter pin supplied by the combined finite245 source.
 IF md5(pg_get_functiondef('smarter_private.original_erased_cash_base_request(bigint,text)'::regprocedure)) IS DISTINCT FROM '1467e44cc7f7871b34eff07f7038019d'
 OR md5(pg_get_functiondef('smarter_private.original_inventory_finite_witness(bigint)'::regprocedure)) IS DISTINCT FROM '0ef0a8a5b9e85633cf4bf8b0cd15c8d7'
 OR md5(pg_get_functiondef('smarter_private.original_inventory_source_ref_md5(jsonb)'::regprocedure)) IS DISTINCT FROM '1411d22a7ad914a80922aeed8bfcf7e6'
 OR md5(pg_get_functiondef('smarter_private.original_erased_cash_base_proof(jsonb,timestamptz)'::regprocedure)) IS DISTINCT FROM 'a2d5ac28a5f07929ed99d6e871dddfa2' THEN
 RAISE EXCEPTION 'original_cash_discharge_source_changed' USING ERRCODE='55000';END IF;
 FOR pin IN SELECT * FROM (VALUES
 ('public.fn_ca_balance_has_its_ledger_row()','2df7b3f67e95b8a6c0abe7ba3faff63c'),
 ('public.fn_ca_chip_ledger_enrich()','5931f47d922eea26ab1ea2b12f3f7c8c'),
 ('public.fn_ca_declare_ledger(text,text,uuid,uuid,text,text[])','2eb458ce27b0116d2f7ad4603ca719dd'),
 ('public.fn_ca_deleted_wallet_credit()','90411405ee2614026ea0a5cc4b19f590'),
 ('public.fn_ca_issuance_leg_is_registered()','abdf1fd11d589957da51f8bd7554324d'),
 ('public.fn_ca_restore_erased_seat_credit(text,uuid,uuid,numeric,uuid,text)','6307d1d0ae4f208de54dd5a0e13985d5'),
 ('public.fn_club_members_ledger_writer()','d9b0429e6c88b7a2dc4e732edab6ed10'),
 ('public.fn_ensure_club_wallet(uuid,uuid)','dd462a9943724d4b94fbe683ed364250'),
 ('public.fn_platform_frozen()','ec683805e052fceeae74789e82dce4cc'),
 ('public.fn_active_maintenance_release_boundary()','05b537b57c9f51a5164e20a1cd0e67e0'),
 ('public.fn_ca_assert_emergency_path(text)','a37722a7445d65bd0c9bdcf62ff36649'),
 ('public.fn_ca_current_epoch()','6a803a80ab2b368acdbded9435112f98'),
 ('public.fn_ca_deleted_wallet_bank_return(uuid,uuid,text)','bccd30228fd808adb885cf3c7f47db88'),
 ('public.fn_ca_ledger_tally_add(text,text,numeric)','03b49d93d25551e4e74dedbb5dc7c08e'),
 ('public.fn_ca_ledger_tally_key(text,uuid,uuid)','7d8c761d9d43c0429448c4b8b588d6ac'),
 ('public.fn_ca_mint_issued_24h(text,uuid)','e0bf5ff9e14f1d9d070fde617b85ea7c'),
 ('public.fn_ca_noncirculating_chip_stores()','0b1f2c1035aa66ee67f3d1f553b8f334'),
 ('public.fn_ca_register_issuance_leg(uuid)','8d3d5e1feccd96fcf0045afefdb9fcdc'),
 ('public.fn_ca_tally_pair(text,numeric,text,numeric)','54e8f073910b0a538bf26d8e625cce33'),
 ('public.fn_cashier_assert_active_actor(uuid)','3ceb097db1a05a550e8b2a42fe931d36'),
 ('public.fn_freeze_bypass_active()','2bfad412c70b965fd9d2c72b2ad83310'),
 ('auth.role()','8a3e05459e07e0633d43c6fba2a2cdf4'),
 ('auth.uid()','ea3b41bf29e2ad573067939329aa088e'),
 ('public.fn_ca_assert_player_action(uuid,text,text)','1f5e930010ce5204e5407001268bd880'),
 ('public.fn_ca_chip_store_declared()','d5b08956826e56a0d414db4bfd022d3b'),
 ('public.fn_ca_felt_counts_table(uuid)','f927a7f671c765112799d5e36bd552ba'),
 ('public.fn_ca_tournament_counts(uuid)','86e9255968e9dbf6e114b41b22f3649a'),
 ('public.fn_club_settlement_frozen(uuid)','93579cd20397b592447167d5ac512189'),
 ('public.fn_union_week_start(timestamp with time zone)','103f192a228084dad0e4268c36c82c4b'),
 ('public.fn_ca_emergency_issuance_guard()','ad9f6b99951af4374934a526fe52660e'),
 ('public.fn_ca_mint_register_append_only()','664af2474324260146684edf8ea9c220'),
 ('public.enforce_chip_ledger_performed_by()','ed92ea331aeddaffca0ae46a7f6801ea'),
 ('public.fn_ca_tally_ledger_leg()','9b3ab2f5a78cb7fa0adfb377706ecb85'),
 ('public.zz_chip_ledger_key_is_claimed_once()','57a2b2eb1bc5b1c5ac36394c2ac23bcd'),
 ('public.fn_refuse_while_frozen()','3a866372172806a8a69cc3d37413f0cc'),
 ('public.fn_cashier_operation_intent_guard()','d89888ea95f0fba54a976fe966804649'),
 ('public.fn_ca_refuse_restricted_transfer()','65a2cb12ec806144a074efc2614563d1'),
 ('public.fn_refuse_operator_move_while_settling()','4dd93ff68d573144d73edc71e166f36f'),
 ('public.fn_cashier_balance_actor_guard()','178146284da8fbab643c2e6fcbb8bd42'),
 ('public.fn_cashier_operation_mutex_guard()','344aae5352ca162b3f89971599fcda78'),
 ('public.fn_ca_autoledger()','852f2e9b202459d7450407b71b7cb6f8'),
 ('public.fn_ca_tally_balance_move()','b7911a245d4bf33134a9a2f474c1f410'),
 ('public.fn_ca_tally_store_move()','ba64376ceff72886b399349b53fcd2fa'),
 ('public.fn_admin_holds_no_player_wallet()','3c54c86c548917606c846febfadf704b'),
 ('public.fn_block_browser_balance_writes()','c7390598f411e7d6bc4b8daf00e12c6e'),
 ('public.fn_guard_retired_club_mutation()','941df8f6c1a4857d46885ddf7c1941d8')) v(signature,body_md5) LOOP
 IF to_regprocedure(pin.signature) IS NULL OR md5(pg_get_functiondef(to_regprocedure(pin.signature))) IS DISTINCT FROM pin.body_md5 THEN RAISE EXCEPTION 'original_cash_discharge_money_source_changed:%',pin.signature USING ERRCODE='55000';END IF;
 END LOOP;
 r:=smarter_private.original_erased_cash_base_request(e,h);
 IF r->>'status' IS DISTINCT FROM 'ready' OR r->'financial_admission' IS DISTINCT FROM 'false'::jsonb
 OR r->>'witness_md5' IS DISTINCT FROM h OR md5((r->'witness')::text) IS DISTINCT FROM h
 OR md5((r->'proof')::text) IS DISTINCT FROM r->>'proof_md5' THEN
 RAISE EXCEPTION 'original_cash_discharge_source_refused' USING ERRCODE='55000';END IF;
 f:=r->'witness';p:=smarter_private.original_erased_cash_base_proof(f,'2026-10-12 07:00:00Z');
 IF p IS DISTINCT FROM r->'proof' OR p->>'status' IS DISTINCT FROM 'ready' THEN
 RAISE EXCEPTION 'original_cash_discharge_proof_refused' USING ERRCODE='55000';END IF;
 u:=(p#>>'{holding,user_id}')::uuid;club:=(p#>>'{holding,club_id}')::uuid;
 a:=(p->>'original_base')::numeric;occ:=(f#>>'{signed,occupancy_id}')::uuid;
 tbl:=(f#>>'{event,before_row,table_id}')::uuid;k:='retired_completed_cash_base:'||occ;
 IF a IS NULL OR a<=0 OR a*100<>trunc(a*100) OR u IS NULL OR club IS NULL OR occ IS NULL OR tbl IS NULL THEN
 RAISE EXCEPTION 'original_cash_discharge_identity_refused' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT 1 FROM smarter_private.original_erased_cash_base_discharges WHERE event_id=e) THEN
 old:=smarter_private.original_erased_cash_base_discharge_receipt(e,h);
 IF old->>'status' IS DISTINCT FROM 'discharged' THEN
 RAISE EXCEPTION 'original_cash_discharge_durable_receipt_refused' USING ERRCODE='55000';END IF;
 RETURN old||jsonb_build_object('replayed',true,'financial_payment',false);END IF;
 -- Reject every orphan/partial key before the raw writer's swallowed unique branch.
 IF EXISTS(SELECT 1 FROM public.wallet_credit_idempotency WHERE key=k)
 OR EXISTS(SELECT 1 FROM public.ca_mint_ledger WHERE op_id=k)
 OR EXISTS(SELECT 1 FROM public.chip_ledger WHERE idempotency_key=k)
 OR EXISTS(SELECT 1 FROM public.chip_transactions WHERE club_id=club AND table_id=tbl AND to_user_id=u AND created_at>='2026-10-06 00:00Z' AND metadata->>'restore_key'=k) THEN
 RAISE EXCEPTION 'original_cash_discharge_orphan_or_partial_key' USING ERRCODE='55000';END IF;
 IF public.fn_platform_frozen() IS DISTINCT FROM false THEN
 RAISE EXCEPTION 'original_cash_discharge_frozen' USING ERRCODE='55000';END IF;
 SELECT chip_treasury,c.owner_id INTO bank_before,owner_id FROM public.clubs c
 WHERE id=club AND asset='chips' AND lifecycle_status='active' FOR UPDATE NOWAIT;
 IF NOT FOUND OR bank_before IS NULL OR owner_id IS NULL THEN
 RAISE EXCEPTION 'original_cash_discharge_bank_changed' USING ERRCODE='55000';END IF;
 SELECT status INTO profile_status FROM public.profiles WHERE id=u FOR SHARE NOWAIT;
 IF NOT FOUND OR profile_status IS DISTINCT FROM 'deleted' THEN
 RAISE EXCEPTION 'original_cash_discharge_deleted_status_changed' USING ERRCODE='55000';END IF;
 SELECT * INTO member FROM public.club_members WHERE club_id=club AND user_id=u FOR UPDATE NOWAIT;
 IF NOT FOUND OR member.status NOT IN('active','approved') OR member.status IS NULL
 OR member.chip_balance IS DISTINCT FROM 0::numeric OR member.held_chips IS DISTINCT FROM 0::numeric
 OR member.locked_chips IS DISTINCT FROM 0::numeric THEN
 RAISE EXCEPTION 'original_cash_discharge_wallet_changed' USING ERRCODE='55000';END IF;
 SELECT md5(to_jsonb(l)::text) INTO before_late FROM public.chip_ledger l WHERE id=(f#>>'{late_ledger,id}')::uuid;
 IF before_late IS NULL OR before_late IS DISTINCT FROM (SELECT x->>'md5' FROM smarter_private.original_inventory_restoration_cases c CROSS JOIN LATERAL jsonb_array_elements(c.source_refs)x WHERE c.event_id=e AND x->>'kind'='chip_ledger' AND x->>'id'=f#>>'{late_ledger,id}') THEN
 RAISE EXCEPTION 'original_cash_discharge_played_ledger_changed' USING ERRCODE='55000';END IF;
 SELECT coalesce(array_agg(t.id),ARRAY[]::uuid[]) INTO before_receipts FROM public.chip_transactions t
 WHERE t.club_id=club AND t.from_user_id=u AND t.transaction_type='club_bank_claim' AND t.amount=a;
 SET CONSTRAINTS ALL DEFERRED;
 r:=public.fn_ca_restore_erased_seat_credit(k,u,club,a,tbl,
 'Original erased cash base restitution; deleted-account funding-club bank custody; event '||e);
 IF r->>'restored' IS DISTINCT FROM 'true' THEN
 RAISE EXCEPTION 'original_cash_discharge_raw_writer_refused' USING ERRCODE='55000';END IF;
 SET CONSTRAINTS ALL IMMEDIATE;
 SELECT count(*) INTO n FROM public.chip_ledger WHERE idempotency_key=k;
 IF n<>1 THEN RAISE EXCEPTION 'original_cash_discharge_issuance_leg_count';END IF;
 SELECT * INTO issuance FROM public.chip_ledger WHERE idempotency_key=k;
 SELECT * INTO idem FROM public.wallet_credit_idempotency WHERE key=k;
 SELECT count(*) INTO n FROM public.ca_mint_ledger WHERE op_id=k;
 IF n<>1 THEN RAISE EXCEPTION 'original_cash_discharge_mint_key_refused';END IF;
 SELECT * INTO mint FROM public.ca_mint_ledger WHERE op_id=k;
 IF issuance.id IS NULL OR issuance.id::text IS DISTINCT FROM r->>'chip_ledger_id'
 OR issuance.from_type IS DISTINCT FROM 'issuance_reserve' OR issuance.to_type IS DISTINCT FROM 'player_wallet'
 OR issuance.to_entity_id IS DISTINCT FROM u OR issuance.club_id IS DISTINCT FROM club
 OR issuance.amount IS DISTINCT FROM a OR issuance.category IS DISTINCT FROM 'refund'
 OR issuance.epoch_id IS DISTINCT FROM public.fn_ca_current_epoch()
 OR issuance.created_at IS DISTINCT FROM transaction_timestamp()
 OR mint.chip_ledger_id IS DISTINCT FROM issuance.id OR mint.holder_id IS DISTINCT FROM u
 OR mint.holder_type IS DISTINCT FROM 'player' OR mint.action IS DISTINCT FROM 'mint'
 OR mint.asset IS DISTINCT FROM 'chips' OR mint.amount IS DISTINCT FROM a
 OR mint.created_at IS DISTINCT FROM transaction_timestamp()
 OR idem.user_id IS DISTINCT FROM u OR idem.amount IS DISTINCT FROM a THEN
 RAISE EXCEPTION 'original_cash_discharge_issuance_refused' USING ERRCODE='55000';END IF;
 SELECT count(*) INTO n FROM public.chip_transactions t WHERE t.club_id=club AND t.table_id=tbl AND t.to_user_id=u AND t.created_at>='2026-10-06 00:00Z' AND t.metadata->>'restore_key'=k;
 IF n<>1 THEN RAISE EXCEPTION 'original_cash_discharge_base_receipt_count';END IF;
 SELECT * INTO base_tx FROM public.chip_transactions t WHERE t.club_id=club AND t.table_id=tbl AND t.to_user_id=u AND t.created_at>='2026-10-06 00:00Z' AND t.metadata->>'restore_key'=k;
 IF base_tx.to_user_id IS DISTINCT FROM u OR base_tx.club_id IS DISTINCT FROM club
 OR base_tx.table_id IS DISTINCT FROM tbl OR base_tx.amount IS DISTINCT FROM a
 OR base_tx.transaction_type IS DISTINCT FROM 'seat_credit_restored'
 OR base_tx.metadata->>'source' IS DISTINCT FROM 'issuance_reserve'
 OR base_tx.created_at IS DISTINCT FROM transaction_timestamp() THEN
 RAISE EXCEPTION 'original_cash_discharge_base_receipt_refused';END IF;
 SELECT count(*) INTO n FROM public.chip_transactions t WHERE t.club_id=club AND t.from_user_id=u
 AND t.transaction_type='club_bank_claim' AND t.amount=a AND NOT(t.id=ANY(before_receipts));
 IF n<>1 THEN RAISE EXCEPTION 'original_cash_discharge_new_bank_receipt_count';END IF;
 SELECT * INTO bank_tx FROM public.chip_transactions t WHERE t.club_id=club AND t.from_user_id=u
 AND t.transaction_type='club_bank_claim' AND t.amount=a AND NOT(t.id=ANY(before_receipts));
 SELECT count(*) INTO n FROM public.chip_ledger WHERE idempotency_key='deleted_account_bank_return:'||(bank_tx.metadata->>'op_id');
 IF n<>1 THEN RAISE EXCEPTION 'original_cash_discharge_bank_leg_count';END IF;
 SELECT * INTO claim FROM public.chip_ledger WHERE idempotency_key='deleted_account_bank_return:'||(bank_tx.metadata->>'op_id');
 IF bank_tx.to_user_id IS DISTINCT FROM owner_id OR bank_tx.metadata->>'reason' IS DISTINCT FROM 'deleted_account'
 OR bank_tx.metadata->>'direction' IS DISTINCT FROM 'into_bank' OR bank_tx.metadata->>'source' IS DISTINCT FROM 'player_wallet'
 OR bank_tx.created_at IS DISTINCT FROM transaction_timestamp()
 OR claim.from_type IS DISTINCT FROM 'player_wallet' OR claim.from_entity_id IS DISTINCT FROM u
 OR claim.to_type IS DISTINCT FROM 'club_treasury' OR claim.to_entity_id IS DISTINCT FROM club
 OR claim.club_id IS DISTINCT FROM club OR claim.amount IS DISTINCT FROM a
 OR claim.category IS DISTINCT FROM 'club_bank_claim'
 OR claim.correlation_id IS DISTINCT FROM (bank_tx.metadata->>'op_id')::uuid
 OR claim.created_at IS DISTINCT FROM transaction_timestamp() THEN
 RAISE EXCEPTION 'original_cash_discharge_bank_receipt_refused';END IF;
 SELECT chip_treasury INTO bank_after FROM public.clubs WHERE id=club;
 IF bank_after-bank_before IS DISTINCT FROM a OR bank_tx.balance_after IS DISTINCT FROM bank_after
 OR (bank_tx.metadata->>'bank_after')::numeric IS DISTINCT FROM bank_after
 OR EXISTS(SELECT 1 FROM public.club_members WHERE user_id=u AND club_id=club
 AND (chip_balance IS DISTINCT FROM 0::numeric OR held_chips IS DISTINCT FROM member.held_chips
 OR locked_chips IS DISTINCT FROM member.locked_chips)) THEN
 RAISE EXCEPTION 'original_cash_discharge_custody_postimage_refused';END IF;
 SELECT md5(to_jsonb(l)::text) INTO after_late FROM public.chip_ledger l WHERE id=(f#>>'{late_ledger,id}')::uuid;
 IF after_late IS DISTINCT FROM before_late
 OR smarter_private.original_erased_cash_base_request(e,h) IS DISTINCT FROM
 jsonb_build_object('status','ready','financial_admission',false,'event_id',e,
 'case_witness_md5',(smarter_private.original_erased_cash_base_request(e,h)->>'case_witness_md5'),
 'witness_md5',h,'witness',f,'proof',p,'proof_md5',md5(p::text)) THEN
 RAISE EXCEPTION 'original_cash_discharge_originals_changed';END IF;
 refs:=jsonb_build_array(
 jsonb_build_object('kind','wallet_credit_idempotency','id',k,'md5',md5(to_jsonb(idem)::text)),
 jsonb_build_object('kind','mint_ledger','id',k,'md5',md5(to_jsonb(mint)::text)),
 jsonb_build_object('kind','chip_ledger','id',issuance.id,'md5',md5(to_jsonb(issuance)::text)),
 jsonb_build_object('kind','chip_ledger','id',claim.id,'md5',md5(to_jsonb(claim)::text)),
 jsonb_build_object('kind','chip_transaction','id',base_tx.id,'md5',md5(to_jsonb(base_tx)::text)),
 jsonb_build_object('kind','chip_transaction','id',bank_tx.id,'md5',md5(to_jsonb(bank_tx)::text)));
 s:=jsonb_build_object('status','discharged','event_id',e,'custody','canonical_deleted_account_bank',
 'occupancy_id',occ,'user_id',u,'funding_club_id',club,'base_cents',(a*100)::bigint,
 'amount',a,'restoration_key',k,'discharged_at',transaction_timestamp(),
 'mint_id',mint.id,'issuance_leg_id',issuance.id,'base_credit_transaction_id',base_tx.id,
 'bank_claim_leg_id',claim.id,'bank_claim_transaction_id',bank_tx.id,'bank_claim_operation_id',bank_tx.metadata->>'op_id',
 'final_player_wallet',0,'bank_increment',a,'bank_before',bank_before,'bank_after',bank_after,'bank_owner_id',owner_id,
 'preserved_played_delta',p->'preserved_played_delta','financial_refs',refs);
 INSERT INTO smarter_private.original_erased_cash_base_discharges
 (event_id,witness_md5,occupancy_id,user_id,funding_club_id,base_cents,restoration_key,discharged_at,evidence,evidence_md5)
 VALUES(e,h,occ,u,club,(a*100)::bigint,k,transaction_timestamp(),s,md5(s::text));
 old:=smarter_private.original_erased_cash_base_discharge_receipt(e,h);
 IF old->>'status' IS DISTINCT FROM 'discharged' THEN
 RAISE EXCEPTION 'original_cash_discharge_consumer_refused';END IF;
 RETURN old||jsonb_build_object('replayed',false,'financial_payment',true);
END$function$

CREATE OR REPLACE FUNCTION smarter_private.original_erased_cash_base_request(p_event_id bigint, p_expected_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE f jsonb;p jsonb;c record;
BEGIN
 SELECT * INTO c FROM smarter_private.original_inventory_restoration_cases WHERE event_id=p_event_id;
 IF NOT FOUND OR c.family IS DISTINCT FROM 'erased_cash_receivable'
 OR p_expected_hash IS NULL THEN
 RETURN jsonb_build_object('status','blocked','reason','unknown_or_changed_original_cash_request');END IF;
 f:=smarter_private.original_inventory_finite_witness(p_event_id);
 IF f IS NULL THEN
 RETURN jsonb_build_object('status','blocked','reason','original_cash_source_refused');END IF;
 f:=f-'original_table_scope'-'original_manifest_scope';
 IF md5(f::text) IS DISTINCT FROM p_expected_hash THEN
 RETURN jsonb_build_object('status','blocked','reason','original_cash_source_refused');END IF;
 p:=smarter_private.original_erased_cash_base_proof(f,'2026-10-12 07:00:00Z');
 IF p->>'status' IS DISTINCT FROM 'ready' OR p->'financial_admission' IS DISTINCT FROM 'false'::jsonb THEN RETURN p;END IF;
 RETURN jsonb_build_object('status','ready','financial_admission',false,'event_id',p_event_id,
 'case_witness_md5',c.witness_md5,'witness_md5',p_expected_hash,'witness',f,'proof',p,'proof_md5',md5(p::text));
END $function$

CREATE OR REPLACE FUNCTION smarter_private.original_erased_cash_discharge_returns(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS TABLE(ledger_id uuid, club_id uuid, user_id uuid, buyins numeric, cashouts numeric, kind text, valid boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE c record;f jsonb;receipt jsonb;h text;
BEGIN
 IF p_union_id IS DISTINCT FROM 'fade0000-0000-0000-0000-000000000001'::uuid
 OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end) OR p_end<=p_start THEN RETURN;END IF;
 FOR c IN SELECT * FROM smarter_private.original_inventory_restoration_cases WHERE family='erased_cash_receivable' LOOP
 f:=smarter_private.original_inventory_finite_witness(c.event_id);
 IF f IS NULL THEN RAISE EXCEPTION 'original_discharge_flow_source_refused' USING ERRCODE='55000';END IF;
 h:=md5((f-'original_table_scope'-'original_manifest_scope')::text);
 receipt:=smarter_private.original_erased_cash_base_discharge_receipt(c.event_id,h);
 IF receipt->>'status'='pending' THEN CONTINUE;END IF;
 IF receipt->>'status' IS DISTINCT FROM 'discharged'
 OR receipt->>'discharged_at' IS NULL OR NOT isfinite((receipt->>'discharged_at')::timestamptz)
 OR receipt->>'custody' IS DISTINCT FROM 'canonical_deleted_account_bank'
 OR receipt->'final_player_wallet' IS DISTINCT FROM '0'::jsonb
 OR receipt->>'occupancy_id' IS DISTINCT FROM f#>>'{event,before_row,occupancy_id}'
 OR receipt->>'restoration_key' IS DISTINCT FROM ('retired_completed_cash_base:'||(f#>>'{event,before_row,occupancy_id}'))
 OR (receipt->>'discharged_at')::timestamptz<='2026-10-12 07:00:00Z'::timestamptz
 OR EXISTS(SELECT 1 FROM public.union_pnl_original_flows old WHERE old.ledger_id=(receipt->>'issuance_leg_id')::uuid)
 THEN RAISE EXCEPTION 'original_discharge_flow_proof_refused' USING ERRCODE='55000';END IF;
 IF (receipt->>'discharged_at')::timestamptz<p_start OR (receipt->>'discharged_at')::timestamptz>=p_end THEN CONTINUE;END IF;
 ledger_id:=(receipt->>'issuance_leg_id')::uuid;club_id:=(receipt->>'funding_club_id')::uuid;user_id:=(receipt->>'user_id')::uuid;
 buyins:=0;cashouts:=(receipt->>'amount')::numeric;kind:='cash_return';valid:=true;RETURN NEXT;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION smarter_private.original_erased_cash_receivables(p_union_id uuid, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE c record;f jsonb;p jsonb;held jsonb:='[]';n integer:=0;total numeric:=0;receipt jsonb;h text;owed numeric;
BEGIN
 IF p_union_id IS DISTINCT FROM 'fade0000-0000-0000-0000-000000000001'::uuid
 OR p_at IS NULL OR NOT isfinite(p_at) OR p_at<'2026-10-12 07:00:00Z'::timestamptz THEN
 RETURN jsonb_build_object('status','blocked','reason','finite_receivable_boundary_refused');END IF;
 FOR c IN SELECT k.* FROM smarter_private.original_inventory_restoration_cases k
 JOIN smarter_private.original_inventory_restoration_certificates z USING(event_id)
 WHERE k.family='erased_cash_receivable' AND z.boundary='2026-10-12 07:00:00Z'::timestamptz
 AND z.witness_md5=k.witness_md5 AND z.original_witness=k.original_witness AND z.proof_md5=md5(z.proof::text) LOOP
 f:=smarter_private.original_inventory_finite_witness(c.event_id);
 IF f IS NULL THEN RETURN jsonb_build_object('status','blocked','reason','original_receivable_source_refused');END IF;
 p:=smarter_private.original_erased_cash_base_proof(f,'2026-10-12 07:00:00Z');
 IF p->>'status' IS DISTINCT FROM 'ready' OR p->'financial_admission' IS DISTINCT FROM 'false'::jsonb
 OR f#>>'{original_table_scope,union_id}' IS DISTINCT FROM p_union_id::text
 OR f#>>'{original_manifest_scope,game_union_id}' IS DISTINCT FROM p_union_id::text
 OR f#>>'{original_manifest_scope,asset}' IS DISTINCT FROM 'chips'
 OR f#>'{original_manifest_scope,unit_scale}' IS DISTINCT FROM '2'::jsonb THEN
 RETURN jsonb_build_object('status','blocked','reason','original_receivable_proof_refused');END IF;
 n:=n+1;total:=total+(p->>'original_base')::numeric;
 owed:=(p->>'original_base')::numeric;
 IF p_at>'2026-10-12 07:00:00Z'::timestamptz THEN
  h:=md5((f-'original_table_scope'-'original_manifest_scope')::text);
  receipt:=smarter_private.original_erased_cash_base_discharge_receipt(c.event_id,h);
  IF receipt->>'status'='discharged' THEN
   IF receipt->>'discharged_at' IS NULL OR NOT isfinite((receipt->>'discharged_at')::timestamptz)
   OR receipt->>'custody' IS DISTINCT FROM 'canonical_deleted_account_bank'
   OR (receipt->>'amount')::numeric IS DISTINCT FROM owed
   OR receipt->>'occupancy_id' IS DISTINCT FROM f#>>'{event,before_row,occupancy_id}'
   OR (receipt->>'discharged_at')::timestamptz<='2026-10-12 07:00:00Z'::timestamptz THEN
    RETURN jsonb_build_object('status','blocked','reason','original_receivable_discharge_refused');END IF;
   IF (receipt->>'discharged_at')::timestamptz<p_at THEN owed:=0;END IF;
  ELSIF receipt->>'status' IS DISTINCT FROM 'pending' THEN
   RETURN jsonb_build_object('status','blocked','reason','original_receivable_discharge_unproven');
  END IF;
 END IF;
 IF owed>0 THEN held:=held||jsonb_build_array(jsonb_build_object('club_id',p#>'{holding,club_id}','user_id',p#>'{holding,user_id}',
 'amount',owed,'kind','original_erased_cash_receivable','source_id',f#>'{event,before_row,occupancy_id}',
 'original_event_id',c.event_id,'preserved_played_delta',p->'preserved_played_delta'));END IF;
 END LOOP;
 IF n IS DISTINCT FROM 7 OR total IS DISTINCT FROM 1845.87::numeric THEN
 RETURN jsonb_build_object('status','blocked','reason','finite_receivable_coverage_refused');END IF;
 RETURN jsonb_build_object('status','ready','holdings',held,'original_total',total,'held_total',(SELECT COALESCE(sum((x->>'amount')::numeric),0) FROM jsonb_array_elements(held)x),'financial_payment',false);
END $function$

CREATE OR REPLACE FUNCTION smarter_private.original_inventory_basis_generation()
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE r jsonb; receipt jsonb; c record; proofs text;source_hash text;source_count bigint;discharges jsonb:='[]';
BEGIN
 IF (SELECT count(*) FROM smarter_private.original_inventory_restoration_cases) IS DISTINCT FROM 245::bigint
 OR (SELECT count(*) FROM smarter_private.original_inventory_restoration_certificates WHERE boundary='2026-10-12 07:00:00Z') IS DISTINCT FROM 245::bigint
 OR smarter_private.original_inventory_proof_sources_match() IS DISTINCT FROM true THEN RETURN NULL;END IF;
 -- Deduplicate shared original authorities; no 4x family source scan.
 FOR r IN SELECT DISTINCT x FROM smarter_private.original_inventory_restoration_cases k CROSS JOIN LATERAL jsonb_array_elements(k.source_refs)x LOOP
 IF r->>'md5' IS NULL OR smarter_private.original_inventory_source_ref_md5(r) IS DISTINCT FROM r->>'md5' THEN RETURN NULL;END IF;
 END LOOP;
 FOR c IN SELECT * FROM smarter_private.original_inventory_restoration_cases WHERE family='erased_cash_receivable' ORDER BY event_id LOOP
 receipt:=smarter_private.original_erased_cash_base_discharge_receipt(c.event_id,md5((c.original_witness-'original_table_scope'-'original_manifest_scope')::text));
 IF receipt->>'status' NOT IN('pending','discharged') OR receipt->>'status' IS NULL THEN RETURN NULL;END IF;
 discharges:=discharges||jsonb_build_array(jsonb_build_object('event_id',c.event_id,'receipt',receipt));
 END LOOP;
 SELECT md5(string_agg(event_id::text||':'||witness_md5||':'||proof_md5,'|' ORDER BY event_id)) INTO proofs
 FROM smarter_private.original_inventory_restoration_certificates WHERE boundary='2026-10-12 07:00:00Z';
 SELECT count(to_regprocedure(signature)),md5(string_agg(signature||':'||md5(pg_get_functiondef(to_regprocedure(signature))),'|' ORDER BY signature)) INTO source_count,source_hash FROM(VALUES ('public.fn_union_pnl_boundary(uuid,timestamptz)'),('public.fn_union_pnl_original_flow_evidence(uuid,timestamptz,timestamptz)'),('public.fn_union_pnl_evidence_report(uuid,timestamptz,timestamptz)'),('smarter_private.original_inventory_basis_generation()'),('smarter_private.original_inventory_proof_sources_match()'))s(signature);
 IF source_count IS DISTINCT FROM 5::bigint OR source_hash IS NULL OR proofs IS NULL THEN RETURN NULL;END IF;
 RETURN 'original-inventory-245-v1:'||md5(source_hash||'|'||proofs||'|'||discharges::text);
END $function$

CREATE OR REPLACE FUNCTION smarter_private.original_inventory_certificate_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE c record;w jsonb;p jsonb;
BEGIN
 IF session_user IS DISTINCT FROM 'postgres' OR current_user IS DISTINCT FROM 'postgres'
 OR nullif(current_setting('request.jwt.claim.role',true),'') IS NOT NULL
 OR NEW.boundary IS DISTINCT FROM '2026-10-12 07:00:00Z'::timestamptz
 OR public.fn_platform_frozen() IS DISTINCT FROM false
 OR smarter_private.original_inventory_proof_sources_match() IS DISTINCT FROM true
 OR NOT pg_try_advisory_xact_lock(hashtextextended('union-pnl-original-inventory-restoration',0)) THEN
 RAISE EXCEPTION 'original_inventory_certificate_insert_caller_refused' USING ERRCODE='55000';END IF;
 SELECT * INTO c FROM smarter_private.original_inventory_restoration_cases WHERE event_id=NEW.event_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'original_inventory_certificate_case_refused' USING ERRCODE='55000';END IF;
 w:=smarter_private.original_inventory_finite_witness(NEW.event_id);
 p:=smarter_private.original_inventory_finite_family_proof(c.family,w,'2026-10-05 07:00:00Z',NEW.boundary);
 IF w IS NULL OR NEW.original_witness IS DISTINCT FROM w OR NEW.witness_md5 IS DISTINCT FROM c.witness_md5
 OR md5(w::text) IS DISTINCT FROM c.witness_md5 OR p->>'status' IS DISTINCT FROM 'ready'
 OR p->'financial_admission' IS DISTINCT FROM 'false'::jsonb
 OR NEW.proof IS DISTINCT FROM p OR NEW.proof_md5 IS DISTINCT FROM md5(p::text) THEN
 RAISE EXCEPTION 'original_inventory_certificate_canonical_reproof_refused' USING ERRCODE='55000';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION smarter_private.original_inventory_finite_family_proof(family text, witness jsonb, lo timestamp with time zone, hi timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE p jsonb;
BEGIN
 IF witness IS NULL OR jsonb_typeof(witness) IS DISTINCT FROM 'object'
 OR lo IS DISTINCT FROM '2026-10-05 07:00:00Z'::timestamptz
 OR hi IS DISTINCT FROM '2026-10-12 07:00:00Z'::timestamptz THEN
 RETURN jsonb_build_object('status','blocked','reason','finite_original_interval_refused');END IF;
 CASE family
 WHEN 'paired_player' THEN
 p:=smarter_private.original_retirement_boundary_proof(witness,lo,hi);
 IF p->'ready' IS DISTINCT FROM 'true'::jsonb THEN RETURN p;END IF;
 p:=p||jsonb_build_object('status','ready');
 WHEN 'paired_chair' THEN p:=smarter_private.original_paired_seat_restoration_proof(witness->'chair',witness->'player',lo,hi);
 WHEN 'closed_player' THEN p:=smarter_private.original_closed_player_proof(witness,lo,hi);
 WHEN 'continued_chair' THEN p:=smarter_private.original_continued_chair_proof(witness,lo,hi);
 WHEN 'returned_cash' THEN p:=smarter_private.original_returned_cash_base_proof(witness,lo,hi);
 WHEN 'erased_cash_receivable' THEN p:=smarter_private.original_erased_cash_base_proof(witness,hi);
 ELSE RETURN jsonb_build_object('status','blocked','reason','unknown_original_proof_family');
 END CASE;
 IF p->>'status' IS DISTINCT FROM 'ready' OR p->'financial_admission' IS DISTINCT FROM 'false'::jsonb THEN
 RETURN jsonb_build_object('status','blocked','reason','original_proof_refused','proof',p);END IF;
 RETURN p;
END $function$

CREATE OR REPLACE FUNCTION smarter_private.original_inventory_finite_witness(p_event_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
AS $function$
DECLARE c record;r jsonb;n integer;distinct_n integer;
BEGIN
 SELECT * INTO c FROM smarter_private.original_inventory_restoration_cases WHERE event_id=p_event_id;
 IF NOT FOUND OR c.original_witness IS NULL OR c.witness_md5 IS DISTINCT FROM md5(c.original_witness::text)
 OR jsonb_typeof(c.source_refs) IS DISTINCT FROM 'array' OR jsonb_array_length(c.source_refs)=0 THEN RETURN NULL;END IF;
 SELECT count(*),count(DISTINCT jsonb_build_array(x->>'kind',x->>'id',x->>'other_id')) INTO n,distinct_n FROM jsonb_array_elements(c.source_refs) x;
 IF n IS DISTINCT FROM distinct_n THEN RETURN NULL;END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(c.source_refs) LOOP
 IF r->>'md5' IS NULL OR r->>'md5' !~ '^[0-9a-f]{32}$'
 OR smarter_private.original_inventory_source_ref_md5(r) IS DISTINCT FROM r->>'md5' THEN RETURN NULL;END IF;
 END LOOP;
 RETURN c.original_witness;
END $function$

CREATE OR REPLACE FUNCTION smarter_private.original_inventory_source_ref_md5(ref jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE n integer;digest text;k text;v_ref_id uuid;v_ref_other uuid;sid bigint;economic jsonb;s record;d record;a record;
BEGIN
 IF ref IS NULL OR jsonb_typeof(ref) IS DISTINCT FROM 'object' OR ref->>'kind' IS NULL THEN RETURN NULL;END IF;
 k:=ref->>'kind';
 IF k='inventory_event' THEN
  sid:=(ref->>'id')::bigint;SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.union_pnl_inventory_events t WHERE t.event_id=sid;
 ELSIF k='migration_source' THEN
  SELECT count(*),min(md5(array_to_string(t.statements,E'\n'))) INTO n,digest FROM supabase_migrations.schema_migrations t
  WHERE t.version=ref->>'id' AND cardinality(t.statements)=1;
 ELSIF k='mint_ledger' THEN
  SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.ca_mint_ledger t WHERE t.op_id=ref->>'id';
 ELSIF k='wallet_credit_idempotency' THEN
  SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.wallet_credit_idempotency t WHERE t.key=ref->>'id';
 ELSE
  v_ref_id:=(ref->>'id')::uuid;
  CASE k
  WHEN 'chip_ledger' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.chip_ledger t WHERE t.id=v_ref_id;
  WHEN 'chip_transaction' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.chip_transactions t WHERE t.id=v_ref_id;
  WHEN 'cash_move' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.cash_participant_moves t WHERE t.id=v_ref_id;
  WHEN 'wallet_transaction' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.wallet_transactions t WHERE t.id=v_ref_id;
  WHEN 'cash_manifest' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.cash_hand_participant_manifests t WHERE t.id=v_ref_id;
  WHEN 'cash_funding' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.cash_participant_funding_receipts t WHERE t.id=v_ref_id;
  WHEN 'tournament_funding' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_participant_funding_receipts t WHERE t.id=v_ref_id;
  WHEN 'original_hand_qualification' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_original_hand_qualification t WHERE t.submission_id=v_ref_id;
  WHEN 'original_hand_restoration' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_original_hand_restorations t WHERE t.submission_id=v_ref_id;
  WHEN 'cash_qualification' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retired_cash_hand_qualification t WHERE t.submission_id=v_ref_id;
  WHEN 'cash_custody' THEN
   v_ref_other:=(ref->>'other_id')::uuid;
   SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retired_cash_hand_custody t WHERE t.submission_id=v_ref_id AND t.user_id=v_ref_other;
  WHEN 'undealt_qualification' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_undealt_paid_entry_qualification t WHERE t.tournament_id=v_ref_id;
  WHEN 'undealt_restoration' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_undealt_paid_entry_restorations t WHERE t.tournament_id=v_ref_id;
  WHEN 'terminal_settlement' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_terminal_settlements t WHERE t.tournament_id=v_ref_id;
  WHEN 'cancellation_receipt' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_cancellation_receipts t WHERE t.tournament_id=v_ref_id;
  WHEN 'tournament_payout' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_payouts t WHERE t.id=v_ref_id;
  WHEN 'tournament_credit' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_accounting_credit_receipts t WHERE t.id=v_ref_id;
  WHEN 'satellite_settlement' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_satellite_settlements t WHERE t.tournament_id=v_ref_id;
  WHEN 'satellite_award' THEN
   v_ref_other:=(ref->>'other_id')::uuid;
   SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_satellite_awards t WHERE t.tournament_id=v_ref_id AND t.user_id=v_ref_other;
  WHEN 'tournament_ticket' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_tickets t WHERE t.id=v_ref_id;
  WHEN 'atomic_economics' THEN
   SELECT count(*),min(md5(jsonb_build_object('hand_id',t.hand_id,'table_id',t.table_id,'hand_number',t.hand_number,
    'payload_hash',t.payload_hash,'stack_result',t.stack_result,'committed_at',t.committed_at,
    'post_commit_completed_at',t.post_commit_completed_at,'post_commit_result',t.post_commit_result)::text)) INTO n,digest
   FROM public.hand_atomic_commits t WHERE t.hand_id=v_ref_id;
  WHEN 'signed_economics' THEN
   SELECT count(*) INTO n FROM smarter_private.hand_submissions t WHERE t.submission_id=v_ref_id;
   IF n IS DISTINCT FROM 1 THEN RETURN NULL;END IF;
   SELECT * INTO s FROM smarter_private.hand_submissions t WHERE t.submission_id=v_ref_id;
   IF NOT FOUND THEN RETURN NULL;END IF;
   IF s.request<>'{}'::jsonb THEN
    economic:=jsonb_build_object('submission_id',s.submission_id,'request_hash',s.request_hash,'table_id',s.table_id,
     'hand_number',s.hand_number,'lease_generation',s.lease_generation,'stacks',s.request->'p_stacks','started_at',s.request#>>'{p_hand_row,started_at}');
   ELSE
    -- Reconstruct only the captured card-free economic DTO under the existing
    -- qualified retention disposal. Missing payload alone is never authority.
    SELECT count(*) INTO n FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id AND t.table_id=s.table_id AND t.hand_number=s.hand_number;
    IF n IS DISTINCT FROM 1 THEN RETURN NULL;END IF;
    SELECT * INTO d FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id AND t.table_id=s.table_id AND t.hand_number=s.hand_number;
    IF NOT FOUND THEN RETURN NULL;END IF;
    SELECT * INTO a FROM public.hand_atomic_commits t WHERE t.hand_id=v_ref_id AND t.table_id=s.table_id AND t.hand_number=s.hand_number;
    IF NOT FOUND OR s.retained_at IS NULL OR NOT isfinite(s.retained_at)
    OR a.post_commit_completed_at IS NULL OR NOT isfinite(a.post_commit_completed_at) OR a.post_commit_result->>'ok' IS DISTINCT FROM 'true'
    OR d.expected->>'kind' IS DISTINCT FROM 'retention_pruned_settled_hand'
    OR d.expected->>'settled' IS DISTINCT FROM 'true' OR d.expected->>'settlement_completed' IS DISTINCT FROM 'true'
    OR d.expected->>'submission_id' IS DISTINCT FROM v_ref_id::text OR d.expected->>'pruned_hand_id' IS DISTINCT FROM v_ref_id::text
    OR d.expected->>'table_id' IS DISTINCT FROM s.table_id::text OR d.expected->>'hand_number' IS DISTINCT FROM s.hand_number::text
    OR d.expected->>'request_hash' IS DISTINCT FROM s.request_hash
    OR (d.expected->>'settlement_completed_at')::timestamptz IS DISTINCT FROM a.post_commit_completed_at
    OR (d.expected->>'disposed_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'disposed_at')::timestamptz)
    OR (d.expected->>'disposed_at')::timestamptz>clock_timestamp()
    OR (d.expected->>'hand_created_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'hand_created_at')::timestamptz)
    OR (d.expected->>'disposed_at')::timestamptz < (d.expected->>'hand_created_at')::timestamptz+interval '8 days'
    OR (d.expected->>'disposed_at')::timestamptz < a.post_commit_completed_at+interval '8 days'
    OR (d.expected->>'disposed_at')::timestamptz < s.retained_at+interval '8 days'
    OR (SELECT horse_retention_days FROM public.hand_history_retention_policy LIMIT 1) IS DISTINCT FROM 8
    THEN RETURN NULL;END IF;
    economic:=ref->'economic';
    IF jsonb_typeof(economic) IS DISTINCT FROM 'object' OR economic->>'submission_id' IS DISTINCT FROM v_ref_id::text
    OR economic->>'request_hash' IS DISTINCT FROM s.request_hash OR economic->>'table_id' IS DISTINCT FROM s.table_id::text
    OR economic->>'hand_number' IS DISTINCT FROM s.hand_number::text OR economic->>'lease_generation' IS DISTINCT FROM s.lease_generation::text
    OR jsonb_typeof(economic->'stacks') IS DISTINCT FROM 'array' OR jsonb_array_length(economic->'stacks')=0
    OR economic->>'started_at' IS NULL OR NOT isfinite((economic->>'started_at')::timestamptz)
    OR (economic->>'started_at')::timestamptz>a.committed_at THEN RETURN NULL;END IF;
   END IF;
   n:=1;digest:=md5(economic::text);
  ELSE RETURN NULL;
  END CASE;
 END IF;
 IF n IS DISTINCT FROM 1 OR digest IS NULL THEN RETURN NULL;END IF;
 RETURN digest;
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range THEN RETURN NULL;
END $function$
